begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values('34000000-0000-4000-8000-000000000001','stock-staff@example.test','{}'),('34000000-0000-4000-8000-000000000002','stock-inactive@example.test','{}');
update public.profiles set is_active=false where id='34000000-0000-4000-8000-000000000002';
create temp table fx(k text primary key,id uuid); grant all on fx to authenticated;
create temp table requests(k text primary key,v jsonb); grant all on requests to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"34000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into fx select 'client',id from public.save_client(auth.uid(),null,null,'Stock','Family',null,null,'EMAIL',null,null);
insert into fx select 'pet',id from public.save_patient(null,(select id from fx where k='client'),null,'Stockdog','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into fx select 'product',id from public.save_catalog_product(null,null,'Rabies vaccine','vaccine','Manufacturer','dose',3500,true);
insert into fx select 'service',id from public.save_catalog_product(null,null,'Exam','service','','visit',9000,true);
select lives_ok($$select public.receive_inventory('35000000-0000-4000-8000-000000000001','35000000-0000-4000-8000-000000000002',(select id from fx where k='product'),'LOT-1',current_date+365,'Clinic',10,'Opening stock')$$,'Receive vaccine stock');
select lives_ok($$select public.receive_inventory('35000000-0000-4000-8000-000000000001','35000000-0000-4000-8000-000000000002',(select id from fx where k='product'),'LOT-1',current_date+365,'Clinic',10,'Opening stock')$$,'Receipt retry idempotent');
select is((select sum(quantity) from public.inventory_movements),10::numeric,'Retry does not duplicate stock');
select throws_ok($$select public.receive_inventory('35000000-0000-4000-8000-000000000001','35000000-0000-4000-8000-000000000002',(select id from fx where k='product'),'LOT-1',current_date+365,'Clinic',11,'Opening stock')$$,'23514',null,'Receipt retry cannot change quantity');
select throws_ok($$select public.adjust_inventory(gen_random_uuid(),'35000000-0000-4000-8000-000000000002',-11,'Count correction')$$,'23514','Insufficient stock','Adjustment cannot make stock negative');
select lives_ok($$select public.create_billing_invoice('35000000-0000-4000-8000-000000000003',(select id from fx where k='client'))$$,'Create draft invoice');
select throws_ok($$select public.issue_billing_invoice('35000000-0000-4000-8000-000000000003',1)$$,'23514',null,'Empty invoice cannot issue');
insert into requests values('live',jsonb_build_object('pet_id',(select id from fx where k='pet'),'lot_id','35000000-0000-4000-8000-000000000002','invoice_id','35000000-0000-4000-8000-000000000003','quantity',1,'dose','1 mL','route','SC','site','right rear leg','veterinarian','Dr Test','veterinarian_license','TEST-ONLY','administered_at',now(),'next_due_on',current_date+365));
select lives_ok($$select public.record_patient_treatment('35000000-0000-4000-8000-000000000004',(select v from requests where k='live'))$$,'Atomic administration');
select lives_ok($$select public.record_patient_treatment('35000000-0000-4000-8000-000000000004',(select v from requests where k='live'))$$,'Administration retry idempotent');
select is((select sum(quantity) from public.inventory_movements),9::numeric,'Exactly one dose removed');
select is((select count(*) from public.billing_invoice_items),1::bigint,'Exactly one invoice charge');
select is((select manufacturer from public.patient_treatments where id='35000000-0000-4000-8000-000000000004'),'Manufacturer','Manufacturer frozen from catalog');
select is((select next_due_on from public.patient_treatments where id='35000000-0000-4000-8000-000000000004'),current_date+365,'Explicit clinical due date retained');
select throws_ok($$select public.record_patient_treatment('35000000-0000-4000-8000-000000000004',(select v||'{"quantity":2}' from requests where k='live'))$$,'23514',null,'Treatment id rejects changed request');
select throws_ok($$select public.record_patient_treatment(gen_random_uuid(),(select v||'{"quantity":20}' from requests where k='live'))$$,'23514','Insufficient stock','Insufficient stock blocks treatment and bill');
select is((select count(*) from public.patient_treatments),1::bigint,'Failed transaction leaves no treatment');
select lives_ok($$select public.receive_inventory('35000000-0000-4000-8000-000000000005','35000000-0000-4000-8000-000000000006',(select id from fx where k='product'),'EXPIRED',(now() at time zone 'America/Denver')::date-1,'Clinic',5,'Historical count')$$,'Receive expired stock for reconciliation');
select throws_ok($$select public.record_patient_treatment(gen_random_uuid(),(select v||'{"lot_id":"35000000-0000-4000-8000-000000000006"}' from requests where k='live'))$$,'23514','Expired stock cannot be administered or dispensed','Expired lot cannot dispense');
select lives_ok($$select public.add_invoice_service('35000000-0000-4000-8000-000000000007','35000000-0000-4000-8000-000000000003',(select id from fx where k='pet'),(select id from fx where k='service'),1)$$,'Charge service without stock');
select throws_ok($$select public.issue_billing_invoice('35000000-0000-4000-8000-000000000003',1)$$,'40001',null,'New invoice lines invalidate stale issue version');
select lives_ok($$select public.issue_billing_invoice('35000000-0000-4000-8000-000000000003',3)$$,'Issue current draft');
select is((select total_cents from public.billing_invoices where id='35000000-0000-4000-8000-000000000003'),12500::bigint,'Issued total calculated in cents');
select lives_ok($$select public.record_patient_treatment('35000000-0000-4000-8000-000000000004',(select v from requests where k='live'))$$,'Original successful treatment retry works after invoice issue');
select throws_ok($$select public.record_patient_treatment(gen_random_uuid(),(select v from requests where k='live'))$$,'23514','A draft invoice is required','Cannot add treatment charge to issued invoice');
select throws_ok($$update public.billing_invoice_items set unit_price_cents=0$$,'42501',null,'Direct charge rewriting denied');
select throws_ok($$delete from public.inventory_movements$$,'42501',null,'Ledger deletion denied');
select lives_ok($$select public.credit_billing_invoice('35000000-0000-4000-8000-000000000008','35000000-0000-4000-8000-000000000003',3500,'Billing correction')$$,'Append accounting credit');
select lives_ok($$select public.credit_billing_invoice('35000000-0000-4000-8000-000000000008','35000000-0000-4000-8000-000000000003',3500,'Billing correction')$$,'Credit retry idempotent');
select throws_ok($$select public.credit_billing_invoice(gen_random_uuid(),'35000000-0000-4000-8000-000000000003',10000,'Too much')$$,'23514','Credit exceeds invoice balance','Overcredit rejected');
select is((select total_cents from public.billing_invoices where id='35000000-0000-4000-8000-000000000003'),12500::bigint,'Credit preserves original total');
select throws_ok($$select public.void_billing_invoice('35000000-0000-4000-8000-000000000003',4,'Void')$$,'23514',null,'Cannot void already credited invoice');
insert into requests values('historical',jsonb_build_object('historical',true,'pet_id',(select id from fx where k='pet'),'quantity',1,'product_name','Prior rabies','manufacturer','External manufacturer','lot_number','UNKNOWN','dose','unknown','route','unknown','veterinarian','External veterinarian','administered_at',now()-interval '1 year','source','External medical record'));
select lives_ok($$select public.record_patient_treatment('35000000-0000-4000-8000-000000000009',(select v from requests where k='historical'))$$,'Historical vaccination import');
select is((select count(*) from public.billing_invoice_items),2::bigint,'Historical import does not bill');
select is((select sum(quantity) from public.inventory_movements where lot_id='35000000-0000-4000-8000-000000000002'),9::numeric,'Credit and historical import do not restore/debit stock');
select throws_ok($$select public.record_patient_treatment(gen_random_uuid(),(select v||'{"invoice_id":"35000000-0000-4000-8000-000000000003"}' from requests where k='historical'))$$,'23514',null,'Historical cannot carry invoice');
select lives_ok($$select public.correct_patient_treatment('35000000-0000-4000-8000-000000000010','35000000-0000-4000-8000-000000000009','Imported in error',null)$$,'Correction appended without erasing original');
select is((select count(*) from public.patient_treatments),2::bigint,'Corrected original retained');

select lives_ok($$select public.create_billing_invoice('35000000-0000-4000-8000-000000000011',(select id from fx where k='client'))$$,'Create invoice to void');
select lives_ok($$select public.add_invoice_service('35000000-0000-4000-8000-000000000012','35000000-0000-4000-8000-000000000011',null,(select id from fx where k='service'),1)$$,'Add service to void fixture');
select lives_ok($$select public.issue_billing_invoice('35000000-0000-4000-8000-000000000011',2)$$,'Issue void fixture');
select throws_ok($$select public.void_billing_invoice('35000000-0000-4000-8000-000000000011',3,' ')$$,'23514',null,'Void requires explanation');
select lives_ok($$select public.void_billing_invoice('35000000-0000-4000-8000-000000000011',3,'Duplicate invoice')$$,'Explicit invoice void');
select is((select total_cents from public.billing_invoices where id='35000000-0000-4000-8000-000000000011'),9000::bigint,'Void retains original total');
select throws_ok($$select public.credit_billing_invoice(gen_random_uuid(),'35000000-0000-4000-8000-000000000011',1,'Already void')$$,'23514',null,'Voided invoice cannot be credited');
select throws_ok($$select public.adjust_inventory(gen_random_uuid(),'35000000-0000-4000-8000-000000000002',0.0001,'Bad precision')$$,'23514',null,'Stock quantities cannot silently round');
select lives_ok($$select public.adjust_inventory('35000000-0000-4000-8000-000000000013','35000000-0000-4000-8000-000000000002',-1,'Damaged dose')$$,'Reasoned waste adjustment');
select lives_ok($$select public.adjust_inventory('35000000-0000-4000-8000-000000000013','35000000-0000-4000-8000-000000000002',-1,'Damaged dose')$$,'Waste retry idempotent');
select is((select sum(quantity) from public.inventory_movements where lot_id='35000000-0000-4000-8000-000000000002'),8::numeric,'Waste retry debits once');
select set_config('request.jwt.claims','{"sub":"34000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*) from public.billing_invoices),0::bigint,'Inactive staff cannot read invoices');
select throws_ok($$select public.adjust_inventory(gen_random_uuid(),'35000000-0000-4000-8000-000000000002',1,'Spoof')$$,'42501','Active staff access required','Inactive staff cannot adjust stock');
set local role anon;
select throws_ok($$select * from public.patient_treatments$$,'42501',null,'Anonymous clinical stock records denied');
reset role;
select ok(exists(select 1 from public.audit_logs where table_name='inventory_movements' and user_id='34000000-0000-4000-8000-000000000001'),'Stock audit attributes actor');

set local role authenticated;
select set_config('request.jwt.claims','{"sub":"34000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.receive_inventory(gen_random_uuid(),gen_random_uuid(),(select id from fx where k='product'),'NAN',current_date+365,'Clinic','NaN'::numeric,'Bad')$$,'23514',null,'NaN receipt rejected');
select throws_ok($$select public.adjust_inventory(gen_random_uuid(),'35000000-0000-4000-8000-000000000002','NaN'::numeric,'Bad')$$,'23514',null,'NaN adjustment rejected');
select throws_ok($$select public.record_patient_treatment(gen_random_uuid(),(select v||'{"quantity":"NaN"}' from requests where k='historical'))$$,'23514',null,'NaN historical quantity rejected');
select throws_ok($$select public.record_patient_treatment(gen_random_uuid(),(select v||'{"administered_at":"-infinity"}' from requests where k='historical'))$$,'23514',null,'Infinite administration rejected');
select throws_ok($$select public.record_patient_treatment(gen_random_uuid(),(select v||'{"next_due_on":"infinity"}' from requests where k='historical'))$$,'23514',null,'Infinite due date rejected');
select throws_ok($$select public.receive_inventory(gen_random_uuid(),gen_random_uuid(),(select id from fx where k='product'),'INF','infinity'::date,'Clinic',1,'Bad')$$,'23514',null,'Infinite lot expiry rejected');
reset role;
select * from finish();
rollback;
